<script setup>
import { reactive, ref } from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MRadioGroup from '../../../components/mds/MRadioGroup.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import MUpload from '../../../components/mds/MUpload.vue';
const props = defineProps({ proposal: { type: Object, default: null }, processing: Boolean, saving: Boolean, error: { type: String, default: '' }, safeAreaStyle: { type: Object, default: () => ({}) } }); const emit = defineEmits(['cancel', 'propose', 'confirm']); const edits = reactive({ date: '', channel: '', result: '', summary: '', selected_person_id: '', selected_org_id: '', score_delta: 0 }); const discard = ref(false); const localError = ref(''); const channels = ['Gặp mặt', 'Điện thoại', 'Email', 'Sự kiện', 'Khác'].map((value) => ({ value, label: value })); const results = ['Tích cực', 'Trung lập', 'Cần theo dõi'].map((value) => ({ value, label: value }));
function candidateCount() { return (props.proposal?.personCandidates?.length || 0) + (props.proposal?.orgCandidates?.length || 0); } function select(files) { if (files[0]) emit('propose', files[0]); } function selectPerson(value) { edits.selected_person_id = value; if (value) edits.selected_org_id = ''; } function selectOrg(value) { edits.selected_org_id = value; if (value) edits.selected_person_id = ''; } function syncProposal() { const p = props.proposal; if (p) { const total = p.personCandidates.length + p.orgCandidates.length; Object.assign(edits, { date: p.extracted.date || '', channel: p.extracted.channel || 'Gặp mặt', result: p.extracted.result || 'Tích cực', summary: p.extracted.summary || '', selected_person_id: total === 1 && p.personCandidates.length === 1 ? String(p.personCandidates[0].id) : '', selected_org_id: total === 1 && p.orgCandidates.length === 1 ? String(p.orgCandidates[0].id) : '', score_delta: p.suggestedScoreDelta || 0 }); } } function confirm() { localError.value = ''; const selected = Number(Boolean(edits.selected_person_id)) + Number(Boolean(edits.selected_org_id)); if (candidateCount() > 1 && selected !== 1) { localError.value = 'Có nhiều kết quả phù hợp. Hãy chọn đúng một người liên hệ hoặc cơ quan trước khi xác nhận.'; return; } emit('confirm', { ...edits, selected_person_id: edits.selected_person_id || undefined, selected_org_id: edits.selected_org_id || undefined }); } defineExpose({ syncProposal });
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Ghi tương tác bằng giọng nói" @back="discard = true"><template #actions><MButton variant="link" class="[&]:h-[var(--mds-mobile-touch-target)]" :disabled="processing || saving" @click="discard = true">Hủy</MButton></template></MMobileTopBar><div class="min-h-0 flex-1 overflow-y-auto"><div class="mds-mobile-gutter-x space-y-4 py-4"><MUpload v-if="!proposal" accept="audio/*" :multiple="false" :max-size-m-b="25" label="Tệp ghi âm" :disabled="processing" @select-files="select" /><p v-if="!proposal" class="text-[12px] text-[var(--mds-text-secondary)]">Chưa thể thu âm trực tiếp trong AMIS Mobile. Chọn tệp ghi âm để AI chuẩn bị đề xuất.</p><template v-else><p class="rounded-lg bg-[var(--mds-brand-50)] px-3 py-2 text-[13px] text-[var(--mds-brand-700)]">Rà soát trước khi xác nhận. Đề xuất sẽ hết hạn lúc {{ proposal.expiresAt }}.</p><label><span class="mb-1 block text-[13px] font-medium">Ngày</span><MInput v-model="edits.date" type="date" /></label><label><span class="mb-1 block text-[13px] font-medium">Kênh</span><MSelect v-model="edits.channel" :options="channels" /></label><label><span class="mb-1 block text-[13px] font-medium">Kết quả</span><MSelect v-model="edits.result" :options="results" /></label><label><span class="mb-1 block text-[13px] font-medium">Nội dung</span><MTextarea v-model="edits.summary" /></label><p v-if="candidateCount() > 1" class="rounded-lg bg-[var(--mds-warning-bg)] px-3 py-2 text-[13px] text-[var(--mds-warning)]">AI tìm thấy nhiều kết quả. Hãy chọn đúng một kết quả trước khi xác nhận.</p><section v-if="proposal.personCandidates.length"><span class="mb-2 block text-[13px] font-medium">Người liên hệ</span><MRadioGroup :model-value="edits.selected_person_id" direction="vertical" :options="proposal.personCandidates.map((item) => ({ value: String(item.id), label: item.name }))" @update:model-value="selectPerson" /></section><section v-if="proposal.orgCandidates.length"><span class="mb-2 block text-[13px] font-medium">Cơ quan</span><MRadioGroup :model-value="edits.selected_org_id" direction="vertical" :options="proposal.orgCandidates.map((item) => ({ value: String(item.id), label: item.name }))" @update:model-value="selectOrg" /></section><label v-if="edits.selected_person_id"><span class="mb-1 block text-[13px] font-medium">Điều chỉnh điểm quan hệ</span><MInput v-model="edits.score_delta" type="number" min="-10" max="10" /><span class="mt-1 block text-[12px] text-[var(--mds-text-secondary)]">Đề xuất từ AI có thể sửa trong khoảng -10 đến 10; máy chủ sẽ kiểm tra lại quyền sửa người liên hệ.</span></label></template><p v-if="error || localError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error || localError }}</p></div></div><footer v-if="proposal" class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full [&]:h-[var(--mds-mobile-touch-target)]" :loading="saving" @click="confirm">Xác nhận ghi tương tác</MButton></footer><MDialog v-model="discard" title="Bỏ đề xuất giọng nói?" type="danger" confirm-text="Bỏ đề xuất" @confirm="emit('cancel')"><p>Đề xuất chưa xác nhận sẽ không tạo tương tác.</p></MDialog></section></template>
